// Included inside the native adapter after its private Cell/LoadProbeJet types.
// Temporary differentiated data below are for commutator diagnostics only.
template<class GhostFill>void NativeAtlasAction(ProbePack(&packs)[2],Real amplitude,Real width,GhostFill fill_gradient){
 static_assert(std::is_same<DevMemSpace,Kokkos::HostSpace>::value,"local native action is Serial CPU only");
 struct Stats{int cells=0;Real mass=0,raw_mass=0,rhs=0,rhsmax=0,g=0,gmax=0,h=0,hmax=0,mixed=0,comm=0,commmax=0;};std::array<Stats,7>stats{};std::array<Real,22>component2{},componentmax{};Real stationary_max=0,dettime=0,Atime=0,value_error=0;
 std::array<std::vector<hyp::Z4cJet<Real>>,2>native;
 std::array<std::array<DvceArray5D<Real>,2>,3>gradient;
 for(int d=0;d<3;++d)for(int r=0;r<2;++r){auto dev=packs[r].dev;gradient[d][r]=DvceArray5D<Real>("temporary native commutator data",dev.extent(0),25,dev.extent(2),dev.extent(3),dev.extent(4));Kokkos::deep_copy(gradient[d][r],0);}
 for(int r=0;r<2;++r){auto&p=packs[r];auto fields=hyp::BindCartesianFields(p.dev);native[r].resize(p.Cells().size());for(size_t i=0;i<p.Cells().size();++i){const auto&c=p.Cells()[i];auto u=LoadProbeJet(fields,p.dev,c,c.reference.state);native[r][i]=u;for(int n=0;n<4;++n){auto a=operator_oracle::Component(u,18+n),b=operator_oracle::Component(c.reference.state,18+n);for(int d=0;d<3;++d)gradient[d][r](c.m,18+n,c.k,c.j,c.i)=a.d[d]-b.d[d];}}}
 for(int d=0;d<3;++d)fill_gradient(gradient[d]);
 std::ofstream spatial("cubed_sphere_native_action_errors.csv");spatial<<std::setprecision(17)<<"region,m,k,j,i,x,y,z,physical_mass,raw_volume,rhs_normalized_norm,first_normalized_norm,second_normalized_norm,mixed_normalized_norm,commutator_normalized_norm\n";
 for(int r=0;r<2;++r){auto&p=packs[r];auto ind=p.pack->pmesh->mb_indcs;for(size_t index=0;index<p.Cells().size();++index){const auto&c=p.Cells()[index];const auto&ref=c.reference;const auto&u=native[r][index];auto exact=native_pulse_oracle::Deviation(c.geometry.x,amplitude,width);hyp::AddBackgroundJet(exact,ref.state);auto connection=rwm::ReferenceConnection(ref,c.geometry.x);auto rhs=typed_support::Core(u,ref,connection),target=typed_support::Core(exact,ref,connection),stationary=typed_support::Core(ref.state,ref,connection);Real eg=0,eh=0,em=0,ec=0,er=0;
  hyp::Z4cJet<Real> zero{};std::array<hyp::Z4cJet<Real>,3>twice;for(int d=0;d<3;++d)twice[d]=LoadProbeJet(hyp::BindCartesianFields(gradient[d][r]),gradient[d][r],c,zero);
  for(int n=0;n<4;++n){auto a=operator_oracle::Component(u,18+n),b=operator_oracle::Component(exact,18+n);value_error=std::max(value_error,std::abs(a.value-b.value)/amplitude);for(int d=0;d<3;++d){eg+=SQR((a.d[d]-b.d[d])/(amplitude/width));for(int e=0;e<3;++e){Real error=(a.dd[d][e]-b.dd[d][e])/(amplitude/SQR(width));eh+=SQR(error);if(d!=e){em+=SQR(error);auto gd=operator_oracle::Component(twice[d],18+n),ge=operator_oracle::Component(twice[e],18+n);ec+=SQR((gd.d[e]-ge.d[d])/(amplitude/SQR(width)));}}}}
  Real weight=c.volume;int ijk[3]={c.i-ind.is,c.j-ind.js,c.k-ind.ks},count[3]={ind.nx1,ind.nx2,ind.nx3};for(int d=0;d<3;++d){int q=std::min(ijk[d],count[d]-1-ijk[d]);if(q<8)weight*=research_interface::norm[q];}
  for(int n=0;n<22;++n){Real scale=(n==0||(n>=1&&n<=6)||n>=18)?amplitude/width:amplitude/SQR(width);Real error=(rhs[n]-target[n])/scale;er+=SQR(error);component2[n]+=weight*SQR(error);componentmax[n]=std::max(componentmax[n],std::abs(error));stationary_max=std::max(stationary_max,std::abs(stationary[n]));}
  Real fm[3][3]{},fa[3][3]{},tr=0,ta=0;int a[6]={0,0,0,1,1,2},b[6]={0,1,2,1,2,2};for(int n=0;n<6;++n){fm[a[n]][b[n]]=fm[b[n]][a[n]]=rhs[1+n];fa[a[n]][b[n]]=fa[b[n]][a[n]]=rhs[8+n];}auto geometry=hyp::Geometry(u.metric);for(int i=0;i<3;++i)for(int j=0;j<3;++j){tr+=geometry.inverse[i][j]*fm[i][j];ta+=geometry.inverse[i][j]*fa[i][j];for(int k=0;k<3;++k)for(int l=0;l<3;++l)ta-=geometry.inverse[i][k]*fm[k][l]*geometry.inverse[l][j]*u.a.k[i][j];}dettime=std::max(dettime,std::abs(geometry.determinant*tr));Atime=std::max(Atime,std::abs(ta));
  int seam=(ijk[1]<4||ijk[1]>=count[1]-4)+(ijk[2]<4||ijk[2]>=count[2]-4);bool masks[7]={true,r==0,r==1,r==1&&ijk[0]<4,r==1&&seam==1,r==1&&seam==2,r==1&&ref.radius>.9};for(int a=0;a<7;++a)if(masks[a]){auto&s=stats[a];++s.cells;s.mass+=weight;s.raw_mass+=c.volume;s.rhs+=weight*er;s.rhsmax=std::max(s.rhsmax,sqrt(er));s.g+=weight*eg;s.gmax=std::max(s.gmax,sqrt(eg));s.h+=weight*eh;s.hmax=std::max(s.hmax,sqrt(eh));s.mixed+=weight*em;s.comm+=weight*ec;s.commmax=std::max(s.commmax,sqrt(ec));}
  spatial<<r<<","<<c.m<<","<<c.k<<","<<c.j<<","<<c.i;for(Real x:c.geometry.x)spatial<<","<<x;spatial<<","<<weight<<","<<c.volume<<","<<sqrt(er)<<","<<sqrt(eg)<<","<<sqrt(eh)<<","<<sqrt(em)<<","<<sqrt(ec)<<"\n";
 }}
 std::ofstream summary("cubed_sphere_native_action.json");summary<<std::setprecision(17)<<"{\"native_field_components\":22,\"added_evolved_fields\":0,\"initial_value_scaled_error\":"<<value_error<<",\"raw_stationary_rhs_max\":"<<stationary_max<<",\"native_det_time_max\":"<<dettime<<",\"native_A_trace_time_max\":"<<Atime<<",\"regions\":[";const char*names[7]={"all","bulk","shell","cube-shell","seam-edge","seam-corner","outer-collar"};for(int r=0;r<7;++r){if(r)summary<<",";auto&s=stats[r];summary<<"{\"region\":\""<<names[r]<<"\",\"cells\":"<<s.cells<<",\"mass\":"<<s.mass<<",\"raw_volume\":"<<s.raw_mass<<",\"native_rhs_normalized_rms\":"<<sqrt(s.rhs/s.mass)<<",\"native_rhs_normalized_linf\":"<<s.rhsmax<<",\"first_normalized_rms\":"<<sqrt(s.g/s.mass)<<",\"first_normalized_linf\":"<<s.gmax<<",\"second_normalized_rms\":"<<sqrt(s.h/s.mass)<<",\"second_normalized_linf\":"<<s.hmax<<",\"mixed_normalized_rms\":"<<sqrt(s.mixed/s.mass)<<",\"commutator_normalized_rms\":"<<sqrt(s.comm/s.mass)<<",\"commutator_normalized_linf\":"<<s.commmax<<"}";}summary<<"],\"components\":[";for(int n=0;n<22;++n)summary<<(n?",":"")<<"{\"native_field\":"<<n<<",\"rhs_normalized_rms\":"<<sqrt(component2[n]/stats[0].mass)<<",\"rhs_normalized_linf\":"<<componentmax[n]<<"}";summary<<"],\"evolution_trajectories\":0,\"full_boundary_method_admitted\":false}"<<std::endl;
}
